import type { AstroIntegration } from 'astro';
import { z } from 'zod';

import { validateOptions } from './validate-options.js';

/**
 * Creates the sitemap integration.
 * @param rawOptions - user supplied options
 */
export default function createPlugin(rawOptions: SitemapOptions): AstroIntegration {
  const validatedOptions = validateOptions(rawOptions);
  if (validatedOptions.filter != null) {
    pages = pages.filter(validatedOptions.filter);
  }
